"""Span helpers for voice observability.

When tracing is not enabled (see :func:`voice_tracing_enabled`), no tracer is
resolved and callers receive detached non-recording spans whose methods are
no-ops. The call observability context, however, is bound whenever any voice
signal is active (see :func:`voice_observability_enabled`), so recorders can
accumulate state for metrics even in metrics-only mode.
"""

from __future__ import annotations

import asyncio
import os
from contextlib import contextmanager, nullcontext
from contextvars import ContextVar
from typing import Any, ContextManager, Dict, Iterator, Mapping, Optional

from opentelemetry import context as otel_context
from opentelemetry import trace
from opentelemetry.sdk.trace import TracerProvider as SdkTracerProvider
from opentelemetry.trace import Span, SpanKind

from rasa.tracing.constants import VOICE_CAPTURE_CONTENT_ENV_VAR_NAME
from rasa.tracing.voice.metrics.instruments import voice_metrics_enabled
from rasa.tracing.voice.recorders.call import CallRecorder
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.shared.context import (
    call_observability_context,
    get_current_call_observability_context,
)

_TRUTHY_ENV_VALUES = {"true", "1", "yes"}

_call_context: ContextVar[Optional[otel_context.Context]] = ContextVar(
    "rasa_voice_call_context", default=None
)


def voice_tracing_enabled() -> bool:
    """Return whether voice spans should be created at all.

    Voice tracing is on only while an OpenTelemetry SDK tracer provider is
    installed globally (done by ``configure_backend_tracing`` when the
    endpoints file configures a tracing backend). Checked at call time so
    late configuration applies.
    """
    return isinstance(trace.get_tracer_provider(), SdkTracerProvider)


def voice_observability_enabled() -> bool:
    """Return whether any voice signal (spans or metrics) is active.

    The call and turn observability contexts are bound, and the stage
    recorders are created and tracked, whenever this is true — even when
    tracing is disabled and every span stays a non-recording no-op.
    """
    return voice_tracing_enabled() or voice_metrics_enabled()


def content_capture_enabled() -> bool:
    """Return whether spoken content (final transcripts) may be stamped on spans.

    Content capture is disabled unless ``RASA_VOICE_CAPTURE_CONTENT`` is set
    to a supported truthy value.
    """
    raw_value = os.environ.get(VOICE_CAPTURE_CONTENT_ENV_VAR_NAME, "")
    return raw_value.strip().lower() in _TRUTHY_ENV_VALUES


_call_root_span: ContextVar[Optional[CallRecorder]] = ContextVar(
    "rasa_voice_call_root_span", default=None
)


def get_current_call_root_span() -> CallRecorder:
    """Return the active call recorder or a detached no-op recorder."""
    call_root_span = _call_root_span.get()
    if call_root_span is not None:
        return call_root_span
    return CallRecorder.detached()


@contextmanager
def voice_call_span(
    *,
    call_id: str,
    conversation_id: str,
    attributes: Optional[Mapping[str, Any]] = None,
) -> Iterator[CallRecorder]:
    """Open the root span for one voice call/session.

    Binds the call's observability context whenever any voice signal is
    active, so recorders can accumulate metric state even without tracing.
    With tracing enabled it additionally opens the root span and binds the
    call's OTel context for the lifetime of the ``with`` block, so spans
    opened by sibling tasks join the same trace and carry the same ids.

    Args:
        call_id: Channel-assigned id of the call.
        conversation_id: The tracker ``sender_id``.
        attributes: Additional identity attributes for the root span (e.g.
            channel name, ASR/TTS provider, locale).

    Yields:
        The root call span's typed recorder (a detached no-op recorder when
        tracing is unconfigured).
    """
    if not voice_observability_enabled():
        yield CallRecorder.detached()
        return

    with call_observability_context(
        call_id=call_id, conversation_id=conversation_id
    ) as observability:
        # Open a root span only when tracing is configured.
        span_context: ContextManager[Span]
        if voice_tracing_enabled():
            span_context = _tracer().start_as_current_span(
                semconv.SPAN_NAME_VOICE_CALL,
                attributes={
                    **observability.get_span_correlation_attributes(),
                    **(attributes or {}),
                },
            )
        else:
            span_context = nullcontext(trace.INVALID_SPAN)

        # Bind one recorder for tracing and metrics-only modes.
        with span_context as span:
            call_root_span = CallRecorder(span, observability)
            root_token = _call_root_span.set(call_root_span)
            call_context_token = (
                _call_context.set(otel_context.get_current())
                if voice_tracing_enabled()
                else None
            )

            try:
                yield call_root_span
            except asyncio.CancelledError:
                call_root_span.record_cancelled()
                raise
            except Exception as error:
                call_root_span.record_failure(error)
                raise
            finally:
                call_root_span.end()
                if call_context_token is not None:
                    _call_context.reset(call_context_token)
                _call_root_span.reset(root_token)


@contextmanager
def voice_call_context() -> Iterator[None]:
    """Re-attach the active call's trace context to the current execution.

    Used when this module's call context was retained but the ambient OTel
    context was lost. No-op when no call span is active.
    """
    stored_context = _call_context.get()
    if stored_context is None:
        yield
        return
    token = otel_context.attach(stored_context)
    try:
        yield
    finally:
        otel_context.detach(token)


@contextmanager
def voice_stage_span(
    name: str,
    *,
    kind: SpanKind = SpanKind.INTERNAL,
    attributes: Optional[Mapping[str, Any]] = None,
) -> Iterator[Span]:
    """Open a voice stage span stamped with the call's correlation ids.

    Parents to the ambient current span — the root call span when the caller
    runs inside the call's task tree (or under :func:`voice_call_context`).

    Args:
        name: Span name, one of the ``SPAN_NAME_*`` constants.
        kind: OTel span kind; ``CLIENT`` for spans wrapping provider calls.
        attributes: Start-time attributes for the span.

    Yields:
        The stage span (no-op span when tracing is unconfigured).
    """
    if not voice_tracing_enabled():
        yield trace.INVALID_SPAN
        return

    span_attributes: Dict[str, Any] = {
        **_correlation_attributes(),
        **(attributes or {}),
    }
    with _tracer().start_as_current_span(
        name, kind=kind, attributes=span_attributes
    ) as span:
        try:
            yield span
        except Exception as error:
            # The context manager records the exception and sets ERROR status;
            # add the stable error.type alongside it before it propagates.
            span.set_attribute(semconv.ERROR_TYPE, _error_type_name(error))
            raise


def start_voice_span(
    name: str,
    *,
    kind: SpanKind = SpanKind.INTERNAL,
    attributes: Optional[Mapping[str, Any]] = None,
    start_time_ns: Optional[int] = None,
) -> Span:
    """Start a voice span that the caller ends explicitly.

    For spans whose open and close live in different callbacks and therefore
    cannot wrap a ``with`` block (e.g. `transcribe audio`, opened on the first
    partial and closed on the final transcript). Parents to the ambient
    current span and carries the call's correlation ids, but is not made
    current itself.

    Args:
        name: Span name, one of the ``SPAN_NAME_*`` constants.
        kind: OTel span kind; ``CLIENT`` for spans wrapping provider calls.
        attributes: Start-time attributes for the span.
        start_time_ns: Epoch nanoseconds to backdate the span's start to
            (``time.time_ns()``); omit to start at the current time.

    Returns:
        The started span; the caller must ``end()`` it on every exit path.
    """
    if not voice_tracing_enabled():
        return trace.INVALID_SPAN

    span_attributes: Dict[str, Any] = {
        **_correlation_attributes(),
        **(attributes or {}),
    }
    return _tracer().start_span(
        name, kind=kind, attributes=span_attributes, start_time=start_time_ns
    )


def _error_type_name(error: BaseException) -> str:
    """Return the stable, low-cardinality `error.type` value for a failure."""
    return type(error).__name__


def set_span_error(span: Span, error: BaseException) -> None:
    """Record an exception on a span and mark it ERROR with a stable error.type.

    Args:
        span: The span to fail; a non-recording span makes this a no-op.
        error: The exception that failed the operation.
    """
    span.record_exception(error)
    span.set_attribute(semconv.ERROR_TYPE, _error_type_name(error))
    span.set_status(trace.Status(trace.StatusCode.ERROR, str(error)))


def add_event_to_current_span(
    name: str, attributes: Optional[Mapping[str, Any]] = None
) -> None:
    """Add an event to the current recording span, if any.

    Args:
        name: Event name, one of the ``EVENT_*`` constants.
        attributes: Bounded event attributes (never content).
    """
    span = trace.get_current_span()
    if not span.is_recording():
        return
    span.add_event(name, attributes=dict(attributes) if attributes else None)


def _correlation_attributes() -> Dict[str, Any]:
    """Return the active call's correlation attributes, or an empty dict."""
    observability = get_current_call_observability_context()
    if observability is None:
        return {}
    return observability.get_span_correlation_attributes()


def _tracer() -> trace.Tracer:
    """Resolve the tracer at call time so late-configured providers apply."""
    return trace.get_tracer_provider().get_tracer(semconv.TRACER_NAME)
